import urllib.request
import json
import time
import re

# Fetch more comprehensive data on all PDB IDs
pdb_ids = []
with open('/app/pdb_ids.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if line:
            pdb_ids.append(line)

print("Fetching detailed PDB info for all structures...")
protein_data = {}

for pdb_id in pdb_ids:
    try:
        url = f'https://data.rcsb.org/rest/v1/core/entry/{pdb_id}'
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=5) as response:
            data = json.loads(response.read())
            if 'struct' in data:
                title = data['struct'].get('title', 'Unknown').upper()
                protein_data[pdb_id] = {'title': title}
                # Classify by keywords
                if 'GREEN' in title or 'GFP' in title:
                    protein_data[pdb_id]['type'] = 'GREEN'
                elif 'BLUE' in title:
                    protein_data[pdb_id]['type'] = 'BLUE'
                elif 'RED' in title or 'RFP' in title or 'MCHERRY' in title:
                    protein_data[pdb_id]['type'] = 'RED'
                elif 'YELLOW' in title or 'YFP' in title:
                    protein_data[pdb_id]['type'] = 'YELLOW'
                elif 'ORANGE' in title:
                    protein_data[pdb_id]['type'] = 'ORANGE'
                else:
                    protein_data[pdb_id]['type'] = 'OTHER'
    except Exception as e:
        pass
    time.sleep(0.1)

# Group by protein type
print("\nProtein Classification:")
for ptype in ['GREEN', 'BLUE', 'YELLOW', 'ORANGE', 'RED', 'OTHER']:
    matching = [p for p, d in protein_data.items() if d.get('type') == ptype]
    if matching:
        print(f"\n{ptype}: {matching}")
        for pid in matching[:2]:
            print(f"  {pid}: {protein_data[pid]['title'][:80]}")

