python3 << 'EOF'
import urllib.request
import json
import time

# Fetch sequences from PDBe API
pdb_ids = ['2IB5', '4KGE', '4Q7T', '1KFD', '5JZL', '6AA7', '3ADF', '5WJ2', '3M22', '2H5Q', '3MGF', '5Y01', '2VZX', '4CQH', '1YZW', '2CHA', '3KZY', '1AK4', '5P21', '1H6R']

print("Fetching sequences from PDBe API...")
sequences = {}

for pdb_id in pdb_ids:
    try:
        url = f'https://www.ebi.ac.uk/pdbe/api/pdb/entry/polymer_entities/{pdb_id.lower()}'
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=3) as response:
            data = json.loads(response.read())
            # Extract first chain sequence
            if pdb_id.lower() in data:
                entities = data[pdb_id.lower()]
                if entities and len(entities) > 0:
                    entity = entities[0]
                    seq = entity.get('sequence', {}).get('chain_a', '')
                    if not seq:
                        # Try to get from entity_poly_seq
                        for ent in entities:
                            if 'polymer_entity_instances' in ent:
                                inst = ent['polymer_entity_instances']
                                if inst and len(inst) > 0:
                                    chain_id = list(inst.keys())[0] if inst else None
                                    if chain_id and 'sequence' in ent:
                                        seq = ent['sequence']
                                        break
                    if seq:
                        sequences[pdb_id] = seq
                        print(f"{pdb_id}: {len(seq)} aa")
    except Exception as e:
        pass
    time.sleep(0.1)

print(f"\nFetched {len(sequences)} sequences")

# If we got some sequences, save them
if sequences:
    with open('/tmp/pdb_sequences.json', 'w') as f:
        json.dump(sequences, f, indent=2)
    print("Saved to /tmp/pdb_sequences.json")

